import {Heading, Link, PageLayout, Stack} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {AlertIcon} from '@primer/octicons-react'
import {ShowHeader} from '../components/show/ShowHeader'
import {Remediation} from '../components/show/remediation/Remediation'
import {ShowLocations} from '../components/show/ShowLocations'
import {ShowTimeline} from '../components/show/ShowTimeline'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {Alert, RelatedAlerts, RelatedPublicLeaks} from '../types/alert-types'
import type {Location, RepoBlobLocation} from '../types/location-types'
import type {Repository} from '../types/repo-types'
import type {PatternInfo} from '../types/pattern-info-types'
import type {TokenMetadata} from '../types/token-metadata-types'
import {ErrorContextBanner} from '../components/shared/ErrorContextBanner'
import {ErrorContextProvider} from '../components/shared/ErrorContext'
import {TimelineContextProvider} from '../components/shared/TimelineContext'
import type {CurrentUser} from '@github-ui/repos-types'
import {CurrentUserProvider} from '@github-ui/current-user'
import {Guidance} from '../components/show/remediation/Guidance'
import {TokenTypePane} from '../components/show/metadata/TokenTypePane'
import {TokenTagsPane} from '../components/show/metadata/TokenTagsPane'
import {RelatedAlertsPane} from '../components/show/metadata/RelatedAlertsPane'
import {RelatedPublicLeaksPane} from '../components/show/metadata/RelatedPublicLeaksPane'
import {GitHubTokenMetadataPane} from '../components/show/metadata/GitHubTokenMetadataPane'
import {AnalyticsProvider} from '@github-ui/analytics-provider'
import type {CopilotSurveyProps} from '@github-ui/copilot-survey/CopilotSurvey'

export interface ShowPayload {
  alert: Alert
  locations: Location[] | undefined | null
  related_alerts: RelatedAlerts
  related_public_leaks: RelatedPublicLeaks
  token_metadata?: TokenMetadata
  repository: Repository
  pattern_info: PatternInfo
  total_locations_count: number
  page: number
  locations_per_page: number
  has_ignored_locations: boolean
  ignored_locations_path?: string
  commit_author_mode: boolean
  show_user_feedback_link: boolean
  user_feedback_notice: string
  host_name: string
  automatic_partner_validity_checks_enabled: boolean
  has_multipart_flag: boolean
  resolve_alerts_allowed: boolean
  wiki_incremental_scans_enabled: boolean
  show_ai_remediation: boolean
  show_generic_secrets_feedback_notice: boolean
  generic_secrets_feedback_notice: string
  one_click_reporting_enabled: boolean
  delegated_closures_enabled: boolean
  existing_closure_request_number: number
  existing_closure_request_pending: boolean
  show_closure_request_review_buttons: boolean
  show_closure_request_cancel_button: boolean
  user_can_review_closure_requests: boolean
  current_user: CurrentUser
  self_serve_banner?: CopilotSurveyProps
}

export function ShowPage() {
  const payload = useRoutePayload<ShowPayload | null>()
  if (!payload) {
    return <Error />
  }

  const user = payload.current_user
  const locations = payload.locations || []

  return (
    <Providers user={user}>
      <ErrorContextBanner />
      <PageLayout>
        <PageLayout.Header>
          <ShowHeader
            alert={payload.alert}
            repository={payload.repository}
            patternInfo={payload.pattern_info}
            commitAuthorMode={payload.commit_author_mode}
            showUserFeedbackLink={payload.show_user_feedback_link}
            userFeedbackNotice={payload.user_feedback_notice}
            resolveAlertsAllowed={payload.resolve_alerts_allowed}
            delegatedClosuresEnabled={payload.delegated_closures_enabled}
            existingClosureRequestNumber={payload.existing_closure_request_number}
            existingClosureRequestPending={payload.existing_closure_request_pending}
            userCanReviewClosureRequests={payload.user_can_review_closure_requests}
            showGenericSecretsFeedbackNotice={payload.show_generic_secrets_feedback_notice}
            genericSecretsFeedbackNotice={payload.generic_secrets_feedback_notice}
            selfServeBanner={payload.self_serve_banner}
          />
        </PageLayout.Header>
        <PageLayout.Content>
          <Remediation
            alert={payload.alert}
            hostName={payload.host_name}
            repo={payload.repository}
            automaticPartnerValidityChecksEnabled={payload.automatic_partner_validity_checks_enabled}
            hasMultipartFlag={payload.has_multipart_flag}
            oneClickReportingAvailable={payload.one_click_reporting_enabled}
          />
          {areLocationsAvailable(locations) && (
            <ShowLocations
              alertNumber={payload.alert.number}
              locations={locations}
              repository={payload.repository}
              totalLocationsCount={payload.total_locations_count}
              page={payload.page}
              locationsPerPage={payload.locations_per_page}
              hasIgnoredLocations={payload.has_ignored_locations}
              ignoredLocationsPath={payload.ignored_locations_path}
              wikiIncrementalScansEnabled={payload.wiki_incremental_scans_enabled}
            />
          )}
          <Guidance
            alert={payload.alert}
            repository={payload.repository}
            hasMetadata={!!payload.token_metadata}
            firstLocation={locations[0] as RepoBlobLocation | undefined}
          />
          <ShowTimeline alertNumber={payload.alert.number} repository={payload.repository} />
        </PageLayout.Content>
        {showMetadataSidebar(payload) && (
          <PageLayout.Pane>
            <Stack>
              <TokenTypePane alert={payload.alert} />
              {showMetadataTags(payload.alert) && <TokenTagsPane alert={payload.alert} />}
              {showRelatedAlerts(payload.alert) && (
                <RelatedAlertsPane relatedAlerts={payload.related_alerts} repository={payload.repository} />
              )}
              {showRelatedPublicLeaks(payload.alert) && (
                <RelatedPublicLeaksPane
                  relatedPublicLeaks={payload.related_public_leaks}
                  repository={payload.repository}
                />
              )}
              {payload.token_metadata && (
                <GitHubTokenMetadataPane
                  metadata={payload.token_metadata}
                  repository={payload.repository}
                  tokenNumber={payload.alert.number}
                />
              )}
            </Stack>
          </PageLayout.Pane>
        )}
      </PageLayout>
    </Providers>
  )
}

function Providers({user, children}: {user: CurrentUser; children: React.ReactNode}) {
  return (
    <ErrorContextProvider>
      <CurrentUserProvider user={user}>
        <AnalyticsProvider appName="secret-scanning" category="remediation" metadata={{}}>
          <TimelineContextProvider>{children}</TimelineContextProvider>
        </AnalyticsProvider>
      </CurrentUserProvider>
    </ErrorContextProvider>
  )
}

function areLocationsAvailable(locations: Location[]) {
  return locations.length > 0
}

function showMetadataSidebar(payload: ShowPayload) {
  if (payload.token_metadata) {
    return true
  }

  if (payload.alert.feature_flags?.secret_scanning_show_single_alert_view_metadata_tags) {
    return true
  }

  if (payload.alert.feature_flags?.secret_scanning_show_single_alert_view_related_alerts) {
    return true
  }

  return false
}

function showMetadataTags(alert: Alert) {
  if (!alert.feature_flags?.secret_scanning_show_single_alert_view_metadata_tags) {
    return false
  }

  return alert.publicly_leaked || alert.multi_repo
}

function showRelatedAlerts(alert: Alert) {
  if (!alert.feature_flags?.secret_scanning_show_single_alert_view_related_alerts) {
    return false
  }
  return alert.multi_repo
}

function showRelatedPublicLeaks(alert: Alert) {
  if (!alert.feature_flags?.secret_scanning_show_single_alert_view_related_alerts) {
    return false
  }
  return alert.publicly_leaked
}

function Error() {
  return (
    <div className="d-flex flex-column flex-justify-center flex-items-center width-full height-screen">
      <Octicon icon={AlertIcon} className="mb-4" size={24} />
      <Heading as="h1">Loading secret failed</Heading>
      <span>
        We track these errors automatically, but if the problem persists feel free to
        <Link href="https://support.github.com/" inline>
          {' '}
          contact us
        </Link>
        .
      </span>
    </div>
  )
}

try{ ShowPage.displayName ||= 'ShowPage' } catch {}
try{ Providers.displayName ||= 'Providers' } catch {}
try{ Error.displayName ||= 'Error' } catch {}