import {IconButton} from '@primer/react'
import {ThumbsdownIcon, ThumbsupIcon, CopilotIcon} from '@primer/octicons-react'
import {Octicon} from '@primer/react/deprecated'
import {useAnalytics} from '@github-ui/use-analytics'
import {useEffect, useState} from 'react'

export function AIRemediationFeedback({stepName}: {stepName: string}) {
  const {sendAnalyticsEvent} = useAnalytics()
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false)
  const [feedbackWasHelpful, setFeedbackWasHelpful] = useState(false)

  useEffect(
    () => {
      sendAnalyticsEvent('secret_scanning_alert.remediation_step.shown', 'REMEDIATION_STEP', {
        category: 'remediation',
        action: 'step_shown',
        label: 'step_shown',
        step_name: stepName,
      })
    },
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  )

  const submitFeedback = (wasHelpful: boolean) => {
    sendAnalyticsEvent('secret_scanning_alert.remediation_step.feedback_received', 'REMEDIATION_STEP', {
      category: 'remediation',
      action: 'feedback_received',
      label: 'feedback_received',
      step_name: stepName,
      helpful: wasHelpful,
    })
    setFeedbackSubmitted(true)
    setFeedbackWasHelpful(wasHelpful)
  }

  return (
    <div className="d-flex" data-testid="secret-scanning-remediation-feedback">
      <div className="flex-1 text-small fgColor-muted pb-3">
        <Octicon icon={CopilotIcon} /> The above information was provided by Copilot.
      </div>
      <div className="d-flex pb-2">
        <IconButton
          data-testid="secret-scanning-remediation-feedback-helpful"
          className={`${feedbackSubmitted && feedbackWasHelpful ? 'fgColor-success' : 'fgColor-muted'}`}
          size="small"
          icon={ThumbsupIcon}
          variant="invisible"
          aria-label="This is helpful."
          disabled={feedbackSubmitted}
          onClick={() => submitFeedback(true)}
        >
          Helpful
        </IconButton>
        <IconButton
          data-testid="secret-scanning-remediation-feedback-not-helpful"
          className={`ml-1 ${feedbackSubmitted && !feedbackWasHelpful ? 'fgColor-danger' : 'fgColor-muted'}`}
          size="small"
          icon={ThumbsdownIcon}
          variant="invisible"
          aria-label="This is not helpful."
          disabled={feedbackSubmitted}
          onClick={() => submitFeedback(false)}
        >
          Not helpful
        </IconButton>
      </div>
    </div>
  )
}

try{ AIRemediationFeedback.displayName ||= 'AIRemediationFeedback' } catch {}