import {Button, Dialog, FormControl, Textarea, Radio, RadioGroup} from '@primer/react'
import {useRef, useState} from 'react'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {secretScanningUpdateClosureRequestPath} from '../../../paths'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {ShowPayload} from '../../../pages/Show'
import {useErrorContext} from '../../../components/shared/ErrorContext'
import {useMutation} from '@github-ui/react-query'
import styles from '../../shared/shared.module.css'

import localStyles from './ClosureRequestReviewButtons.module.css'
import {clsx} from 'clsx'

class NoCommentError extends Error {
  constructor() {
    super()
    this.name = 'NoCommentError'
  }
}

export function ClosureRequestReviewButtons() {
  const [isOpen, setIsOpen] = useState(false)
  const [selectedRadioValue, setSelectedRadioValue] = useState('')
  const [commentValidationError, setCommentValidationError] = useState(false)
  const reviewCommentTextArea = useRef<HTMLTextAreaElement>(null)
  const errorContext = useErrorContext()
  const payload = useRoutePayload<ShowPayload | null>()
  const repoName = payload?.repository?.name
  const closureRequestNumber = payload?.existing_closure_request_number
  const owner = payload?.repository?.owner_display_login

  const url = secretScanningUpdateClosureRequestPath(owner ?? '', repoName ?? '', closureRequestNumber ?? 0)
  const updateExemptionRequestMutation = useMutation({
    mutationFn: async () => {
      const commentText = reviewCommentTextArea?.current?.value
      if (!commentText) {
        throw new NoCommentError()
      }
      const response = await reactFetchJSON(`${url}`, {
        method: 'PUT',
        body: {
          status: selectedRadioValue,
          message: commentText,
          repository: repoName,
        },
      })
      const data = await response.json()
      if (response.status !== 201) {
        return data?.error
      }
      return null
    },
    onSuccess: () => {
      setIsOpen(false)
      window.location.reload()
    },
    onError: error => {
      if (error instanceof NoCommentError) {
        setCommentValidationError(true)
      } else {
        setCommentValidationError(false)
        errorContext.showError(error.toString())
      }
    },
  })

  if (!closureRequestNumber) {
    // The closure request number should always be present in the payload, but add the error check in case.
    errorContext.showError('Error: Closure request number not found')
    return
  }

  if (!repoName) {
    // The repository name should always be present in the payload, but add the error check in case.
    errorContext.showError('Error: Repository name not found')
    return
  }

  if (!owner) {
    // The owner should always be present in the payload, but add the error check in case.
    errorContext.showError('Error: Repository owner not found')
    return
  }

  return (
    <>
      <Button size="small" variant="primary" onClick={() => setIsOpen(!isOpen)}>
        Review request
      </Button>
      {isOpen && (
        <Dialog
          className={clsx(`${styles.secretScanningDialog}`, localStyles.Dialog)}
          title="Review request"
          onClose={() => setIsOpen(false)}
        >
          <form
            onSubmit={e => {
              e.preventDefault()
              updateExemptionRequestMutation.mutate()
            }}
          >
            <FormControl required>
              <FormControl.Label>Comment</FormControl.Label>
              <Textarea
                className="mb-3 width-full"
                ref={reviewCommentTextArea}
                placeholder="Feedback to go with your review..."
              />
              {commentValidationError && (
                <FormControl.Validation variant="error">This field is required</FormControl.Validation>
              )}
            </FormControl>

            <RadioGroup
              name="defaultRadioGroup"
              onChange={(selected: string | null) => setSelectedRadioValue(selected ?? '')}
              aria-label="Approve or deny this request"
            >
              <RadioGroup.Label visuallyHidden>Approve or deny this request</RadioGroup.Label>
              <FormControl>
                <Radio value="reject" />
                <FormControl.Label>
                  <span className="text-bold">Deny request</span>
                </FormControl.Label>
                <FormControl.Caption>Submit feedback on why alert cannot be dismissed</FormControl.Caption>
              </FormControl>
              <FormControl>
                <Radio value="approve" />
                <FormControl.Label>
                  <span className="text-bold">Approve request</span>
                </FormControl.Label>
                <FormControl.Caption>Submit feedback and alert will be automatically dismissed</FormControl.Caption>
              </FormControl>
            </RadioGroup>
            <div className="Box-footer mt-2 d-flex flex-justify-end">
              <Button
                type="submit"
                variant="primary"
                disabled={
                  !selectedRadioValue || selectedRadioValue.length === 0 || updateExemptionRequestMutation.isPending
                }
              >
                Submit review
              </Button>
            </div>
          </form>
        </Dialog>
      )}
    </>
  )
}

try{ ClosureRequestReviewButtons.displayName ||= 'ClosureRequestReviewButtons' } catch {}