import type {Query} from './query'
import type {Repository} from './repo-types'

export const BlankslateType = {
  Disabled: 'disabled',
  LoadingFailed: 'loadingfailed',
} as const

export type BlankslateType = (typeof BlankslateType)[keyof typeof BlankslateType]

export interface BlankslatePayload {
  blankslate_type: BlankslateType
  repository: Repository
  adminable: boolean
  help_url: string
  query?: Query
}

export interface BlankslateEnterprisePayload extends BlankslatePayload {
  enterprise_contact_path: string
}
