import {Ago} from '@github-ui/ago'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {Header, Link} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {IssueOpenedIcon, CommentDiscussionIcon, GitPullRequestIcon, AlertIcon} from '@primer/octicons-react'
import {type ContentLocation, ContentType} from '../../../types/location-types'
import type {Repository} from '../../../types/repo-types'
import {getContentPath} from '../../../paths'
import styles from './ContentLocationComponent.module.css'

export function ContentLocationComponent({location, repository}: {location: ContentLocation; repository: Repository}) {
  return (
    <div data-testid={'content-location-container'} className={styles.Box}>
      <Header style={{display: 'flex'}} className={styles.Header}>
        {renderHeaderIcon(location.content_type)}
        {renderHeaderContent(
          repository,
          location.content_number,
          location.heading_text,
          location.is_deleted,
          location.is_user_hidden,
          location.content_type,
          location.content_id,
        )}
      </Header>
      <div className={styles.Box_1}>
        {location.is_deleted ? (
          <>
            <Octicon icon={AlertIcon} className={styles.Octicon} />
            <span className={styles.Text}>{`${getContentArtifact(location.content_type)} deleted`}</span>
          </>
        ) : (
          <>
            {location.author.avatar_url ? (
              <GitHubAvatar
                size={16}
                src={location.author.avatar_url}
                data-testid="issue-author-avatar"
                className={styles.Octicon}
              />
            ) : null}
            <div className={styles.Box_2}>
              <span className={styles.Text}>{`${location.author.display_login} commented`}</span>
              <Ago sx={{ml: 1, fontSize: 0}} timestamp={new Date(location.created_at)} />
              {location.editor ? (
                <span className={styles.Text_2}>{`• edited by ${location.editor.display_login}`}</span>
              ) : null}
              {location.is_user_hidden ? <span className={styles.Text_2}>{`• hidden`}</span> : null}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

function renderHeaderIcon(contentType: ContentType): JSX.Element | null {
  switch (contentType) {
    case ContentType.IssueBody:
    case ContentType.IssueTitle:
    case ContentType.IssueComment:
      return (
        <div data-testid="issue-opened-icon" className={styles.Box_3}>
          <Octicon icon={IssueOpenedIcon} className={styles.Octicon_1} />
        </div>
      )
    case ContentType.DiscussionTitle:
    case ContentType.DiscussionBody:
    case ContentType.DiscussionComment:
      return (
        <div data-testid="comment-discussion-icon" className={styles.Box_3}>
          <Octicon icon={CommentDiscussionIcon} className={styles.Octicon_1} />
        </div>
      )
    case ContentType.PullRequestTitle:
    case ContentType.PullRequestBody:
    case ContentType.PullRequestComment:
    case ContentType.PullRequestReview:
    case ContentType.PullRequestReviewComment:
      return (
        <div data-testid="git-pull-request-icon" className={styles.Box_3}>
          <Octicon icon={GitPullRequestIcon} className={styles.Octicon_1} />
        </div>
      )
    default:
      return null
  }
}

function renderHeaderContent(
  repository: Repository,
  contentNumber: number,
  text: string,
  isDeleted: boolean,
  isHidden: boolean,
  contentType: ContentType,
  contentId: number,
): JSX.Element {
  if (isDeleted) {
    return <span className={styles.Text_1}>{text}</span>
  } else {
    const path = getContentPath(repository, contentType, contentNumber, contentId)
    if (path === '') {
      return <span className={styles.Text_1}>{text}</span>
    }
    return (
      <Link href={path} className={styles.Link}>
        {text}
      </Link>
    )
  }
}

function getContentArtifact(content_type: ContentType): string {
  switch (content_type) {
    case ContentType.IssueBody:
    case ContentType.IssueTitle:
      return 'Issue'
    case ContentType.DiscussionBody:
    case ContentType.DiscussionTitle:
      return 'Discussion'
    case ContentType.PullRequestBody:
    case ContentType.PullRequestTitle:
      return 'Pull Request'
    case ContentType.IssueComment:
    case ContentType.DiscussionComment:
    case ContentType.PullRequestComment:
    case ContentType.PullRequestReview:
    case ContentType.PullRequestReviewComment:
      return 'Comment'
    default:
      return 'Content'
  }
}

try{ ContentLocationComponent.displayName ||= 'ContentLocationComponent' } catch {}